interface Calculator {
  add: (n: number) => Calculator;
  subtract: (n: number) => Calculator;
  multiply: (n: number) => Calculator;
  divide: (n: number) => Calculator;
  clear: () => Calculator;
  result: () => number;
  memoryStore: () => Calculator;
  memoryAdd: () => Calculator;
  memoryClear: () => Calculator;
  memoryRecall: () => number;
}

export function createCalculator(): Calculator {
  const current: number = 0;
  const memory: number = 0;

  const calc: Calculator = {} as Calculator;

  calc.add = (n: number) => {
    current += n;
    return calc;
  };

  calc.subtract = (n: number) => {
    current -= n;
    return calc;
  };

  calc.multiply = (n: number) => {
    current *= n;
    return calc;
  };

  calc.divide = (n: number) => {
    if (n !== 0) {
      current /= n;
    } else {
      current = NaN;
    }
    return calc;
  };

  calc.clear = () => {
    current = 0;
    return calc;
  };

  calc.result = () => current;

  calc.memoryStore = () => {
    memory = current;
    return calc;
  };

  calc.memoryAdd = () => {
    memory += current;
    return calc;
  };

  calc.memoryClear = () => {
    memory = 0;
    return calc;
  };

  calc.memoryRecall = () => memory;

  return calc;
}
