export interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const storage = new Map<string, { count: number; windowStart: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      let state = storage.get(key);

      if (state === undefined) {
        state = { count: 0, windowStart: nowMs };
        storage.set(key, state);
      }

      if (nowMs - state.windowStart >= windowMs) {
        state.windowStart = nowMs;
        state.count = 0;
      }

      if (state.count < limit) {
        state.count++;
        return true;
      }

      return false;
    },
    remaining(key: string, nowMs: number): number {
      let state = storage.get(key);

      if (state === undefined) {
        state = { count: 0, windowStart: nowMs };
        storage.set(key, state);
      }

      if (nowMs - state.windowStart >= windowMs) {
        state.windowStart = nowMs;
        state.count = 0;
      }

      return limit - state.count;
    },
    reset(key: string): void {
      storage.delete(key);
    }
  };
}
