```typescript
interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}

export function createTtlCache(): TtlCache {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();
  const defaultTtl = 1000;

  const set: TtlCache['set'] = (key, value, nowMs, ttlMs) => {
    const expiresAt = nowMs + (ttlMs ?? defaultTtl);
    cache.set(key, { value, expiresAt });
  };

  const get: TtlCache['get'] = (key, nowMs) => {
    const entry = cache.get(key);
    if (!entry) return undefined;
    if (nowMs >= entry.expiresAt) {
      cache.delete(key);
      return undefined;
    }
    return entry.value;
  };

  const has: TtlCache['has'] = (key, nowMs) => {
    const entry = cache.get(key);
    if (!entry) return false;
    if (nowMs >= entry.expiresAt) {
      cache.delete(key);
      return false;
    }
    return true;
  };

  const delete: TtlCache['delete'] = (key) => {
    return cache.delete(key);
  };

  const size: TtlCache['size'] = (nowMs) => {
    const keysToDelete: string[] = [];
    for (const [key, entry] of cache.entries()) {
      if (nowMs >= entry.expiresAt) {
        keysToDelete.push(key);
      }
    }
    for (const key of keysToDelete) {
      cache.delete(key);
    }
    return cache.size();
  };

  const clear: TtlCache['clear'] = () => {
    cache.clear();
  };

  return { set, get, has, delete, size, clear } satisfies TtlCache;
}
