type Listener = (payload: unknown) => unknown

export interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Array<{ func: Listener; once: boolean }>>()
  const emittedOnce = new Map<string, Set<Listener>>()

  function getListeners(event: string): Array<{ func: Listener; once: boolean }> {
    let list = listeners.get(event)
    if (list === undefined) {
      list = []
      listeners.set(event, list)
    }
    return list
  }

  function on(event: string, listener: Listener): number {
    const list = getListeners(event)
    list.push({ func: listener, once: false })
    return list.length
  }

  function once(event: string, listener: Listener): number {
    const list = getListeners(event)
    list.push({ func: listener, once: true })
    return list.length
  }

  function off(event: string, listener: Listener): boolean {
    let list = listeners.get(event)
    if (list === undefined) {
      return false
    }
    const index = list.findIndex(l => l.func === listener)
    if (index !== -1) {
      list.splice(index, 1)
      if (list.length === 0) {
        listeners.delete(event)
      }
      return true
    }
    return false
  }

  function emit(event: string, payload: unknown): unknown[] {
    let list: Array<{ func: Listener; once: boolean } | undefined> = listeners.get(event)
    if (list === undefined || list.length === 0) {
      return []
    }

    const results: unknown[] = []
    for (const item of list) {
      if (item === undefined) {
        continue
      }
      const result = item.func(payload)
      results.push(result)

      if (item.once) {
        if (!emittedOnce.has(event)) {
          emittedOnce.set(event, new Set())
        }
        emittedOnce.get(event)!.add(item.func)
      }
    }

    return results
  }

  function listenerCount(event: string): number {
    const list = getListeners(event)
    return list.length
  }

  function cleanupEmittedOnce(event: string): void {
    const emitted = emittedOnce.get(event)
    if (emitted === undefined) {
      return
    }
    let list: Array<{ func: Listener; once: boolean } | undefined> = listeners.get(event)
    if (list === undefined) {
      return
    }

    const filtered = list.filter(l => {
      if (!l) {
        return false
      }
      return !emitted.has(l.func)
    })

    listeners.set(event, filtered)
    emittedOnce.set(event, new Set())
  }

  function onWithCleanup(event: string, listener: Listener): number {
    const list = getListeners(event)
    list.push({ func: listener, once: false })
    return list.length
  }

  function onceWithCleanup(event: string, listener: Listener): number {
    const list = getListeners(event)
    list.push({ func: listener, once: true })
    emittedOnce.get(event)?.add(listener)
    return list.length
  }

  function emitWithCleanup(event: string, payload: unknown): unknown[] {
    cleanupEmittedOnce(event)
    let list = listeners.get(event)
    if (list === undefined) {
      return []
    }

    const results: unknown[] = []
    for (const item of list) {
      if (item === undefined) {
        continue
      }
      const result = item.func(payload)
      results.push(result)
      if (item.once) {
        emittedOnce.get(event)?.add(item.func)
      }
    }

    return results
  }

  return {
    on: onWithCleanup,
    once: onceWithCleanup,
    off,
    emit: emitWithCleanup,
    listenerCount
  }
}
