export type RateLimiterEntry = {
  lastTimestamp: number;
  count: number;
};

export function createRateLimiter(): {
  isAllowed: (key: string, nowMs: number) => boolean;
  reset: (key: string) => void;
} {
  const records: Map<string, RateLimiterEntry> = new Map();

  const WINDOW_DURATION = 1000;
  const MAX_REQUESTS = 3;

  return {
    isAllowed: (key: string, nowMs: number): boolean => {
      let entry = records.get(key);

      if (!entry) {
        // First request for this key - start new window
        entry = { lastTimestamp: nowMs, count: 1 };
        records.set(key, entry);
        return true;
      }

      const elapsed = nowMs - entry.lastTimestamp;

      // Check if window has fully elapsed
      if (elapsed >= WINDOW_DURATION) {
        // Start fresh window with this request
        entry.lastTimestamp = nowMs;
        entry.count = 1;
        return true;
      }

      // Check if we've hit the limit
      if (entry.count >= MAX_REQUESTS) {
        return false;
      }

      // Increment count and allow request
      entry.count += 1;
      return true;
    },

    reset: (key: string): void => {
      records.delete(key);
    }
  };
}

```typescript
export function createRateLimiter(): RateLimiter {
  type State = {
    count: number
    windowStart: number
  }

  const store = new Map<string, State>()
  const limit = 3
  const windowMs = 1000

  return {
    allow(key: string, nowMs: number): boolean {
      let state: State | undefined = store.get(key)

      // Check if window expired
      if (state == null || nowMs - state.windowStart >= windowMs) {
        state = { count: 0, windowStart: nowMs }
        store.set(key, state)
      }
      if (state == null) return false

      if (state.count < limit) {
        state.count += 1
        return true
      }
      return false
    },

    remaining(key: string, nowMs: number): number {
      let state = store.get(key)

      if (state == null) {
        return limit
      }

      // Check if window expired
      if (nowMs - state.windowStart >= windowMs) {
        return limit
      }

      // Ensure we don't return negative remaining
      if (state.count < limit) {
        const remaining = limit - state.count
        return remaining > 0 ? remaining : 0
      }

      return 0
    },

    reset(key: string): void {
      store.delete(key)
    },
  }
}
