  listTodos: () => Array<{ id: number; text: string; completed: boolean }>;
  listCompleted: () => Array<{ id: number; text: string; completed: boolean }>;
  listPending: () => Array<{ id: number; text: string; completed: boolean }>;
  clearCompleted: () => void;
} {
  let idCounter = 0;
  const todos: Array<{ id: number; text: string; completed: boolean }> = [];

  const addTodo = (text: string) => {
    const newTodo = {
      id: idCounter++,
      text,
      completed: false
    };
    todos.push(newTodo);
    return newTodo;
  };

  const getTodo = (id: number) => {
    const indexedTodos = todos.map(t => (t.id === id ? t : null));
    return todos.find(t => t.id === id) || undefined;
  };

  const toggleTodo = (id: number) => {
    const todo = todos.find(t => t.id === id);
    if (todo !== undefined) {
      todo.completed = !todo.completed;
    }
  };

  const deleteTodo = (id: number) => {
    const item = todos.find(t => t.id === id);
    if (item !== undefined) {
      todos.splice(todos.indexOf(item), 1);
      return true;
    }
    return false;
  };

  const listTodos = () => todos.slice();

  const listCompleted = () => todos.filter(t => t.completed);

  const listPending = () => todos.filter(t => !t.completed);

  const clearCompleted = () => {
    todos = todos.filter(t => !t.completed);
  };

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted
  };
};

export { createTodoApp };
