export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  const store = new Map<string, { value: unknown; expiresAt: number }>();

  function isExpired(key: string, nowMs: number): boolean {
    const entry = store.get(key);
    if (!entry) return true;
    return nowMs >= entry.expiresAt;
  }

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const ttl = ttlMs ?? 1000;
      store.set(key, { value, expiresAt: nowMs + ttl });
    },

    get(key: string, nowMs: number): unknown {
      if (!isExpired(key, nowMs)) {
        return store.get(key)!.value;
      }
      store.delete(key);
      return undefined;
    },

    has(key: string, nowMs: number): boolean {
      const entry = store.get(key);
      if (!entry) return false;
      return nowMs < entry.expiresAt;
    },

    delete(key: string): boolean {
      return store.delete(key);
    },

    size(nowMs: number): number {
      let count = 0;
      for (const entry of store.values()) {
        if (nowMs < entry.expiresAt) {
          count++;
        }
      }
      return count;
    },

    clear(): void {
      store.clear();
    },
  };
}
