export function createTtlCache(): TtlCache {
  const store = new Map<string, { value: unknown; expiresAt: number }>()

  function _getExpiresAt(key: string): number | undefined {
    const entry = store.get(key)
    return entry ? entry.expiresAt : undefined
  }

  return {
    set: (key: string, value: unknown, nowMs: number, ttlMs: number = 1000): void => {
      const expiresAt = nowMs + ttlMs
      store.set(key, { value, expiresAt })
    },
    get: (key: string, nowMs: number): unknown => {
      const entry = store.get(key)
      if (!entry) {
        return undefined
      }
      if (nowMs >= entry.expiresAt) {
        store.delete(key)
        return undefined
      }
      return entry.value
    },
    has: (key: string, nowMs: number): boolean => {
      const entry = store.get(key)
      if (!entry) {
        return false
      }
      return nowMs < entry.expiresAt
    },
    delete: (key: string): boolean => {
      // If exists but expired, we still delete it
      const exists = _getExpiresAt(key) !== undefined
      store.delete(key)
      return exists
    },
    size: (nowMs: number): number => {
      let count = 0
      for (const [key, entry] of store.entries()) {
        if (nowMs < entry.expiresAt) {
          count++
        }
      }
      return count
    },
    clear: (): void => {
      store.clear()
    }
  }
}

export interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}
