export function createCalculator(): Calculator {
  let currentValue: number = 0
  let memory: number = 0

  interface Calculator {
    add(n: number): Calculator
    subtract(n: number): Calculator
    multiply(n: number): Calculator
    divide(n: number): Calculator
    clear(): Calculator
    result(): number
    memoryStore(): Calculator
    memoryRecall(): number
    memoryClear(): Calculator
    memoryAdd(): Calculator
  }

  const impl: Calculator = {
    add(n: number): Calculator {
      currentValue += n
      return this
    },
    subtract(n: number): Calculator {
      currentValue -= n
      return this
    },
    multiply(n: number): Calculator {
      currentValue *= n
      return this
    },
    divide(n: number): Calculator {
      if (n !== 0) {
        currentValue /= n
      }
      return this
    },
    clear(): Calculator {
      currentValue = 0
      return this
    },
    result(): number {
      return currentValue
    },
    memoryStore(): Calculator {
      memory = currentValue
      return this
    },
    memoryRecall(): number {
      return memory
    },
    memoryClear(): Calculator {
      memory = 0
      return this
    },
    memoryAdd(): Calculator {
      memory += currentValue
      return this
    }
  }

  return impl
}
