export function createEventEmitter(): {
  on<T extends string>(eventName: T, listener: (...args: unknown[]) => unknown): void
  off<T extends string>(eventName: T, listener: (...args: unknown[]) => unknown): void
  emit<T extends string, U extends unknown[]>(eventName: T, ...args: U): U extends [infer R, ...never[]] ? R : never
} {
  const listeners = new Map<string, Array<(...args: unknown[]) => unknown>>()

  function on<T extends string>(eventName: T, listener: (...args: unknown[]) => unknown): void {
    if (!listeners.has(eventName)) {
      listeners.set(eventName, [])
    }
    listeners.get(eventName)!.push(listener)
  }

  function off<T extends string>(eventName: T, listener: (...args: unknown[]) => unknown): void {
    const eventListeners = listeners.get(eventName)
    if (!eventListeners) {
      return
    }
    const index = eventListeners.indexOf(listener)
    if (index !== -1) {
      eventListeners.splice(index, 1)
    }
  }

  function emit<T extends string, U extends unknown[]>(eventName: T, ...args: U): U extends [infer R, ...infer _] ? R : never {
    if (eventListeners) {
      listeners.forEach((listeners) => {
        listeners.forEach((listener) => {
          const result = listener(...args)
          if (result) {
            returnResults.push(result)
          }
        })
      })
    }
    return returnResults
  }

  return { on, off, emit }
}
