export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Array<{listener: Listener, once: boolean}>>()

  return {
    on(event: string, listener: Listener): number {
      if (!listeners.has(event)) {
        listeners.set(event, [])
      }
      const list = listeners.get(event)!
      list.push({listener, once: false})
      return list.length
    },

    once(event: string, listener: Listener): number {
      if (!listeners.has(event)) {
        listeners.set(event, [])
      }
      const list = listeners.get(event)!
      list.push({listener, once: true})
      return list.length
    },

    off(event: string, listener: Listener): boolean {
      const eventListeners = listeners.get(event)
      if (!eventListeners) return false

      const index = eventListeners.findIndex(l => l.listener === listener)
      if (index !== -1) {
        eventListeners.splice(index, 1)
        return true
      }
      return false
    },

    emit(event: string, payload: unknown): unknown[] {
      const eventListeners = listeners.get(event)
      if (!eventListeners) return []

      const results: unknown[] = []
      for (let i = 0; i < eventListeners.length; i++) {
        const {listener, once} = eventListeners[i]
        const result = listener(payload)
        results.push(result)
        if (once) {
          eventListeners.splice(i, 1)
          i--
        }
      }
      return results
    },

    listenerCount(event: string): number {
      const list = listeners.get(event)
      return list ? list.length : 0
    }
  }
}
