export function createRateLimiter() {
  const policy = { maxRequests: 3, windowMs: 1000 } as const;
  const store = new Map<string, { count: number; windowStart: number }>();

  function reset(key: string) {
    store.set(key, { count: 0, windowStart: 0 });
  }

  function getAll() {
    return store.map(s => s).filter(s => s.count > 0);
  }

  function isRateLimited(key: string, nowMs: number) {
    const record = store.get(key);
    const elapsedSinceWindowStart = nowMs - record.windowStart;
    const elapsedSinceWindowStartCapped = Math.min(elapsedSinceWindowStart, policy.windowMs);
    const reset = record.count <= 0 || elapsedSinceWindowStartCapped > policy.windowMs;
    let count = record.count;
    return reset ? { allowed: true } : count >= policy.maxRequests ? { allowed: false } : { allowed: true };
  }

  function check(key: string, nowMs: number) {
    const { maxRequests, windowMs } = policy;
    const storeKey = store.get(key) || { count: 0, windowStart: nowMs };
    const windowElapsed = nowMs - storeKey.windowStart;

    let allowed = true;

    if (nowMs - storeKey.windowStart > windowMs) {
      storeKey.windowStart = nowMs;
      storeKey.count = 0;
    }

    if (storeKey.count >= maxRequests) {
      allowed = false;
    } else {
      storeKey.count++;
    }

    return allowed;
  }

  function getRemaining(key: string, nowMs: number) {
    if (!store.has(key)) {
      store.set(key, { count: 0, windowStart: nowMs });
      return policy.maxRequests;
    }
    const record = store.get(key)!;
    const elapsed = nowMs - record.windowStart;
    let remaining = 0;

    if (record.count > 0 && elapsed <= policy.windowMs) {
      remaining = Math.max(0, policy.maxRequests - record.count);
    } else if (elapsed > policy.windowMs) {
      remaining = policy.maxRequests;
    }

    return remaining;
  }

  function getRemainingMs(key: string, nowMs: number) {
    if (!store.has(key)) {
      store.set(key, { count: 0, windowStart: nowMs });
      return policy.windowMs;
    }
    const record = store.get(key)!;
    const elapsed = nowMs - record.windowStart;

    if (elapsed > policy.windowMs) {
      return policy.windowMs;
    }

    const remaining = Math.max(0, policy.maxRequests - record.count);
    if (remaining <= 0) {
      return -1;
    }

    const resetAt = record.windowStart + policy.windowMs;
    return resetAt - nowMs;
