    if (remaining <= 0) {
      return -1;
    }

    const resetAt = record.windowStart + policy.windowMs;
    return resetAt - nowMs;
  }

  return {
    check: (key: string, nowMs: number) => {
      const { maxRequests, windowMs } = policy;
      if (!store.has(key)) {
        store.set(key, { count: 0, windowStart: nowMs });
      }
