export function createRateLimiter(): RateLimiter {
  const store = new Map<string, { count: number; windowStart: number }>()
  const RATE_LIMIT = 3
  const WINDOW_MS = 1000

  return {
    allow(key: string, nowMs: number): boolean {
      const currentEntry = store.get(key)

      // Reset: if nowMs is at least windowMs after windowStart, start fresh window
      if (currentEntry && nowMs - currentEntry.windowStart >= WINDOW_MS) {
        store.set(key, { count: 0, windowStart: nowMs })
        return true
      }

      // Key not tracked yet or same window - check limit
      if (!currentEntry) {
        store.set(key, { count: 0, windowStart: nowMs })
      }

      const entry = store.get(key)!

      if (entry.count < RATE_LIMIT) {
        entry.count++
        return true
      }
      return false
    },

    remaining(key: string, nowMs: number): number {
      const currentEntry = store.get(key)
      let entry = currentEntry

      // Reset if we're in a new window
      if (currentEntry && nowMs - currentEntry.windowStart >= WINDOW_MS) {
        store.set(key, { count: 0, windowStart: nowMs })
        entry = { count: 0, windowStart: nowMs }
      } else if (!currentEntry) {
        // Key doesn't exist, effectively unlimited
        return RATE_LIMIT
      }

      // Remaining is limit minus current count, but not below 0
      return Math.max(0, RATE_LIMIT - entry.count)
    },

    reset(key: string): void {
      store.delete(key)
    }
  }
}

export interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}
