function createTodoApp(): {
  addTodo: (text: string) => { id: number; text: string; completed: boolean }
  getTodo: (id: number) => { id: number; text: string; completed: boolean } | undefined
  toggleTodo: (id: number) => void
  deleteTodo: (id: number) => boolean
  listTodos: () => Array<{ id: number; text: string; completed: boolean }>
  listCompleted: () => Array<{ id: number; text: string; completed: boolean }>
  listPending: () => Array<{ id: number; text: string; completed: boolean }>
  clearCompleted: () => void
} {
  let idCounter = 1
  const todos: Array<{ id: number; text: string; completed: boolean }> = []

  return {
    addTodo: (text: string) => {
      const id = idCounter++
      const todo = { id, text, completed: false }
      todos.push(todo)
      return todo
    },
    getTodo: (id: number) => {
      return todos.find((todo) => todo.id === id)
    },
    toggleTodo: (id: number) => {
      const index = todos.findIndex((todo) => todo.id === id)
      if (index !== -1) {
        todos[index].completed = !todos[index].completed
      }
    },
    deleteTodo: (id: number) => {
      const index = todos.findIndex((todo) => todo.id === id)
      if (index !== -1) {
        todos.splice(index, 1)
        return true
      }
      return false
    },
    listTodos: () => {
      return todos
    },
    listCompleted: () => {
      const completed = todos.filter((todo) => todo.completed)
      return completed.filter((n) => n.id) as any
    },
    listPending: () => {
      const pending = todos.filter((todo) => !todo.completed)
      return pending.filter((n) => n.id) as any
    },
    clearCompleted: () => {
      const startIndex = todos.findIndex((todo) => todo.completed)
      if (startIndex !== -1) {
        todos.splice(startIndex)
      }
    },
  }
}

export { createTodoApp }
