function createTodoApp(): TodoApp {
  const todos = new Map<number, Todo>();
  let nextId = 1;

  const addTodo = (text: string): Todo => {
    const todo: Todo = {
      id: nextId++,
      text,
      completed: false
    };
    todos.set(todo.id, todo);
    return todo;
  };

  const getTodo = (id: number): Todo | undefined => {
    return todos.get(id);
  };

  const toggleTodo = (id: number): void => {
    const todo = todos.get(id);
    if (todo) {
      todo.completed = !todo.completed;
    }
  };

  const deleteTodo = (id: number): boolean => {
    const removed = todos.delete(id);
    return removed;
  };

  const listTodos = (): Todo[] => {
    return Array.from(todos.values());
  };

  const listCompleted = (): Todo[] => {
    return Array.from(todos.values()).filter(todo => todo.completed);
  };

  const listPending = (): Todo[] => {
    return Array.from(todos.values()).filter(todo => !todo.completed);
  };

  const clearCompleted = (): void => {
    const idsToDelete = Array.from(todos.keys()).filter(id => todos.get(id)?.completed);
    idsToDelete.forEach(id => todos.delete(id));
  };

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted
  };
}

export { createTodoApp };

