export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  const store = new Map<string, { value: unknown; expiresAt: number }>()

  const defaultTtl = 1000

  return {
    set(key, value, nowMs, ttlMs = defaultTtl) {
      const expiresAt = nowMs + (ttlMs ?? defaultTtl)
      store.set(key, { value, expiresAt })
    },
    get(key, nowMs) {
      const entry = store.get(key)
      if (!entry) return undefined
      if (nowMs >= entry.expiresAt) return undefined
      return entry.value
    },
    has(key, nowMs) {
      const entry = store.get(key)
      if (!entry) return false
      return nowMs < entry.expiresAt
    },
    delete(key) {
      return store.delete(key) !== undefined
    },
    size(nowMs) {
      let count = 0
      for (const entry of store.values()) {
        if (nowMs < entry.expiresAt) count++
      }
      return count
    },
    clear() {
      store.clear()
    },
  }
}
