export function createTtlCache(): TtlCache {
  const cache = new Map<string, number & { value: unknown }>()

  function isExpired(nowMs: number): boolean {
    const entry = cache.get(key)
    if (!entry) return false
    return nowMs >= entry.expiration
  }

  return {
    set: function (key: string, value: unknown, nowMs: number, ttlMs: number = 1000): void {
      const expiresAt = nowMs + ttlMs
      cache.set(key, {
        value,
        expiration: expiresAt,
      })
    },
    get: function (key: string, nowMs: number): unknown {
      const entry = cache.get(key)
      if (!entry) return undefined
      if (nowMs >= entry.expiration) return undefined
      return entry.value
    },
    has: function (key: string, nowMs: number): boolean {
      const entry = cache.get(key)
      if (!entry) return false
      if (nowMs >= entry.expiration) return false
      return true
    },
    delete: function (key: string): boolean {
      const deleted = cache.delete(key)
      return deleted
    },
    size: function (nowMs: number): number {
      let count = 0
      for (const [, entry] of cache.entries()) {
        if (nowMs < entry.expiration) {
          count++
        }
      }
      return count
    },
    clear: function (): void {
      cache.clear()
    },
  }
}

interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}
